//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_control_basis(value: *mut Isolette_Thermostat_Rust::MonitorControlBasis) -> bool;
  fn get_monitor_mode(value: *mut Isolette_Thermostat_Rust::ThermostatMode) -> bool;
  fn put_alarm_control(value: *mut Isolette_Thermostat_Rust::AlarmCommand) -> bool;
}

pub fn unsafe_get_control_basis() -> Isolette_Thermostat_Rust::MonitorControlBasis
{
  unsafe {
    let value: *mut Isolette_Thermostat_Rust::MonitorControlBasis = &mut Isolette_Thermostat_Rust::MonitorControlBasis::default();
    get_control_basis(value);
    return *value;
  }
}

pub fn unsafe_get_monitor_mode() -> Isolette_Thermostat_Rust::ThermostatMode
{
  unsafe {
    let value: *mut Isolette_Thermostat_Rust::ThermostatMode = &mut Isolette_Thermostat_Rust::ThermostatMode::default();
    get_monitor_mode(value);
    return *value;
  }
}

pub fn unsafe_put_alarm_control(value: &Isolette_Thermostat_Rust::AlarmCommand) -> bool
{
  unsafe {
    return put_alarm_control(value as *const Isolette_Thermostat_Rust::AlarmCommand as *mut Isolette_Thermostat_Rust::AlarmCommand);
  }
}

//////////////////////////////////////////////////////////////////////////////////
// Testing Versions
//////////////////////////////////////////////////////////////////////////////////

#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_control_basis: Mutex<Option<Isolette_Thermostat_Rust::MonitorControlBasis>> = Mutex::new(None);
  pub static ref IN_monitor_mode: Mutex<Option<Isolette_Thermostat_Rust::ThermostatMode>> = Mutex::new(None);
  pub static ref OUT_alarm_control: Mutex<Option<Isolette_Thermostat_Rust::AlarmCommand>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_control_basis.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_monitor_mode.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_alarm_control.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_control_basis(value: *mut Isolette_Thermostat_Rust::MonitorControlBasis) -> bool
{
  unsafe {
    let guard = IN_control_basis.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn get_monitor_mode(value: *mut Isolette_Thermostat_Rust::ThermostatMode) -> bool
{
  unsafe {
    let guard = IN_monitor_mode.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn put_alarm_control(value: *mut Isolette_Thermostat_Rust::AlarmCommand) -> bool
{
  unsafe {
    *OUT_alarm_control.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
